// Landing and after (src/landing.js) and review finding PO-5 (src/state-levels.js): the mission's phase by GMT days,
// the "Getting ready for landing" card on the example flight (Elly's aerobic capacity crossing NASA's 80% before
// landing, Tom's above it, no strength test in flight, the exercise weeks, the eye exam 30 days before return), what to
// expect on return with NASA sources, recovery against the pre-flight level after landing instead of a forecast, and,
// with no mission set, no forecast and nothing explained away as a change of flight.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createMachine } from '../src/engine.js';
import { CELLS, CREW, SHIP } from '../src/config.js';
import { exampleFlight, MISSION } from '../src/demo-crew.js';
import { flightDay } from '../src/mission.js';
import { assess, measureState, hasMissionDates, LEVEL } from '../src/state-levels.js';
import {
  LANDING_RULES, LANDING_SOURCES, RETURN_FACTS, missionPhase, landingPrep, recovery, recoveryLine, weeklyMinutes, preLandingEyeExam, fmtDay,
} from '../src/landing.js';

const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const iso = (t) => new Date(t).toISOString();
const STATE = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };
const person = (id) => CREW.find((c) => c.id === id);
const cell = (ind) => CELLS.find((c) => c.indicator === ind);
const LONG_DASHES = /[\u2013\u2014]/;

function machineWith(readings) {
  const m = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: STATE });
  for (const r of [...readings].sort((a, b) => Date.parse(a.time) - Date.parse(b.time))) m.receive({ person: 'crew-1', ...r });
  return m;
}
let flight = null;
function exampleMachine() {
  if (flight) return flight;
  flight = createMachine({ cells: CELLS, crew: [...CREW, SHIP], state: STATE });
  for (const ev of exampleFlight(CREW)) {
    if (ev.kind === 'reading') flight.receive({ ...ev.reading, person: ev.person, time: ev.time, example: true });
    else flight.review(ev.person, ev.time);
  }
  return flight;
}

test('the phase by GMT days: none without dates, before launch, in flight (near from 30 days, a draft), after landing as R+n', () => {
  const own = { launch: '2026-06-01', landing: '2026-12-10' };
  const M = { launch: '2026-06-01T12:00:00Z', landing: '2026-12-10T12:00:00Z' };
  assert.deepEqual(missionPhase({ launch: null, landing: null, today: '2026-11-15T00:00:00Z' }, '2026-11-15T00:00:00Z'), { kind: 'none' });
  assert.deepEqual(missionPhase(null, '2026-11-15T00:00:00Z'), { kind: 'none' });
  assert.equal(missionPhase(M, '2026-05-29T10:00:00Z').kind, 'before');
  const far = missionPhase(M, '2026-10-01T10:00:00Z');
  assert.equal(far.kind, 'flight');
  assert.equal(far.near, false);
  const near = missionPhase(M, '2026-11-15T06:00:00Z');
  assert.equal(near.near, true);
  assert.equal(near.daysToLanding, 25, '15 Nov to 10 Dec: 25 days by the calendar, as the date next to it says');
  assert.equal(missionPhase(M, '2026-11-09T23:00:00Z').near, false, '31 days before');
  assert.deepEqual([missionPhase(M, '2026-11-10T00:30:00Z').near, missionPhase(M, '2026-11-10T00:30:00Z').daysToLanding], [true, 30], 'from 30 days before');
  assert.equal(missionPhase(M, '2026-12-09T20:00:00Z').daysToLanding, 1, 'the evening before: tomorrow');
  assert.equal(missionPhase(M, '2026-12-10T08:00:00Z').daysToLanding, 0, 'the landing day, before the midday the own mission uses: today, not tomorrow');
  assert.equal(missionPhase(M, '2026-12-10T20:00:00Z').kind, 'flight', 'the landing day is the last flight day, as on the status line');
  const after = missionPhase(M, '2026-12-13T09:00:00Z');
  assert.deepEqual([after.kind, after.n, after.short], ['after', 3, 'R+3']);
  for (const t of ['2026-05-29T10:00:00Z', '2026-07-01T00:00:00Z', '2026-12-10T23:00:00Z', '2026-12-11T01:00:00Z']) {
    assert.equal(missionPhase(M, t).kind, flightDay(own, Date.parse(t)).kind, t);
  }
  assert.equal(LANDING_RULES.nearDays, 30);
  assert.equal(LANDING_RULES.draft, true);
});

test('the example flight: Elly\'s aerobic capacity crosses NASA\'s 80% before landing (attention), Tom\'s stays above it', () => {
  const machine = exampleMachine();
  const now = MISSION.today;
  const elly = landingPrep({ machine, person: person('crew-2'), cells: CELLS, mission: MISSION, now });
  const tom = landingPrep({ machine, person: person('crew-1'), cells: CELLS, mission: MISSION, now });
  // The example follows the calendar: landing is 25.5 days after the start of this hour, so 25 or 26 calendar days.
  assert.equal(elly.daysToLanding, Math.floor(Date.parse(MISSION.landing) / DAY) - Math.floor(Date.parse(now) / DAY));
  assert.ok([25, 26].includes(elly.daysToLanding), String(elly.daysToLanding));
  assert.deepEqual(elly.rows.map((r) => r.key), ['vo2max', 'strength', 'exercise', 'eyes']);
  const ev = elly.rows[0];
  assert.equal(ev.level, LEVEL.ATTENTION);
  assert.equal(ev.state, 'crossing');
  assert.ok(Date.parse(ev.crossing) < Date.parse(MISSION.landing) && Date.parse(ev.crossing) > Date.parse(now));
  assert.ok(ev.atPct < LANDING_RULES.minPercent && ev.pct >= LANDING_RULES.minPercent, `${ev.pct} now, ${ev.atPct} at landing`);
  assert.match(ev.text, /a made-up example level/);
  assert.match(ev.text, /not a medical model/);
  assert.equal(elly.level, LEVEL.ATTENTION);
  // The same story as the levels of Today.
  assert.ok(assess({ machine, person: person('crew-2'), cells: CELLS, mission: MISSION, now }).body.items.some((x) => x.kind === 'forecast' && x.cell.indicator === 'vo2max'));
  assert.equal(tom.rows[0].level, LEVEL.FINE);
  assert.ok(tom.rows[0].atPct > LANDING_RULES.minPercent);
  for (const p of [elly, tom]) {
    const s = p.rows.find((r) => r.key === 'strength');
    assert.equal(s.state, 'none', 'no strength tests in flight in the example');
    assert.match(s.text, /within 5 to 7 days of landing/);
    const e = p.rows.find((r) => r.key === 'eyes');
    assert.equal(e.state, 'done');
    assert.ok(e.value < 20 && e.level === LEVEL.FINE);
    const x = p.rows.find((r) => r.key === 'exercise');
    assert.equal(x.weeks.length, LANDING_RULES.exerciseWeeks);
    assert.ok(x.weeks.every((w) => w.minutes > 0));
    assert.equal(x.level, LEVEL.FINE, 'recorded, not judged');
  }
  const minutes = (p) => p.rows.find((r) => r.key === 'exercise').weeks[0].minutes;
  assert.ok(minutes(elly) < minutes(tom), 'Elly exercises less, the made-up story behind her falling line');
  assert.equal(elly.expect, RETURN_FACTS);
});

test('no landing card more than 30 days before landing, and none without a mission', () => {
  const machine = machineWith([]);
  const M = { launch: '2026-06-01T12:00:00Z', landing: '2026-12-10T12:00:00Z', today: '2026-10-01T12:00:00Z' };
  assert.equal(landingPrep({ machine, person: person('crew-1'), cells: CELLS, mission: M, now: M.today }), null);
  assert.equal(landingPrep({ machine, person: person('crew-1'), cells: CELLS, mission: { launch: null, landing: null, today: M.today }, now: M.today }), null);
  assert.equal(recovery({ machine, person: person('crew-1'), cells: CELLS, mission: M, now: M.today }), null, 'no recovery in flight');
});

test('exercise minutes week by week, newest first; the eye exam 30 days before return: due, late, scanned, done', () => {
  const now = Date.parse('2026-11-15T12:00:00Z');
  const list = [{ time: iso(now - DAY), value: 60 }, { time: iso(now - 2 * DAY), value: 30 }, { time: iso(now - 8 * DAY), value: 45 }, { time: iso(now - 40 * DAY), value: 99 }, { time: iso(now - DAY), value: 'x' }];
  assert.deepEqual(weeklyMinutes(list, now, 4).map((w) => [w.minutes, w.days]), [[90, 2], [45, 1], [0, 0], [0, 0]]);
  const p = person('crew-1');
  const mission = (days) => ({ launch: '2026-06-01T12:00:00Z', landing: iso(now + days * DAY), today: iso(now) });
  const exam = (readings, days) => preLandingEyeExam({ machine: machineWith(readings), person: p, mission: mission(days), now, cells: CELLS });
  assert.equal(exam([], 40).state, 'due');
  assert.match(exam([], 40).text, /30 days before landing/);
  assert.equal(exam([], 25).state, 'late');
  const due = now + 25 * DAY - 30 * DAY;
  const scan = { source: 'oct-scanner', indicator: 'octScan', value: 'scan', time: iso(due - 2 * DAY) };
  assert.equal(exam([scan], 25).state, 'scanned');
  const result = (v) => ({ source: 'oct-result', indicator: 'octChange', value: v, time: iso(due - DAY) });
  assert.deepEqual([exam([scan, result(8)], 25).state, exam([scan, result(8)], 25).level], ['done', LEVEL.FINE]);
  assert.equal(exam([scan, result(24)], 25).level, LEVEL.ATTENTION, "at or above NASA's 20 micrometre line");
  assert.equal(exam([scan, result(60)], 25).level, LEVEL.ACTION, "at or above NASA's 55 micrometre line");
  assert.match(exam([scan, result(24)], 25).text, /a draft line here/);
  assert.equal(exam([{ ...scan, time: iso(due - 9 * DAY) }], 25).state, 'late', 'a scan more than a week early is not this exam');
});

test('after landing: no forecast to a landing that is past; recovery against the pre-flight level from the readings since', () => {
  const M = { launch: '2026-06-01T12:00:00Z', landing: '2026-11-01T12:00:00Z', today: '2026-11-15T12:00:00Z' };
  const at = (s) => `${s}T08:00:00.000Z`;
  const machine = machineWith([
    { source: 'fitness-test', indicator: 'vo2max', value: 42, time: at('2026-05-01') },
    { source: 'fitness-test', indicator: 'vo2max', value: 36, time: at('2026-07-01') },
    { source: 'fitness-test', indicator: 'vo2max', value: 35, time: at('2026-09-01') },
    { source: 'fitness-test', indicator: 'vo2max', value: 34, time: at('2026-10-01') },
    { source: 'fitness-test', indicator: 'vo2max', value: 33.6, time: at('2026-11-08') },
    { source: 'pulse-meter', indicator: 'pulse', value: 70, time: at('2026-04-01') },
    { source: 'pulse-meter', indicator: 'pulse', value: 72, time: at('2026-04-20') },
    { source: 'pulse-meter', indicator: 'pulse', value: 68, time: at('2026-05-20') },
    { source: 'pulse-meter', indicator: 'pulse', value: 84, time: at('2026-11-14') },
    { source: 'mass-device', indicator: 'bodyMass', value: 97, time: at('2026-11-10') },
    { source: 'sleep-tracker', indicator: 'sleep', value: 7.2, time: at('2026-11-15') },
  ]);
  const p = person('crew-1');
  assert.equal(measureState({ machine, person: p, cell: cell('vo2max'), mission: M, now: M.today }).forecast, null);
  assert.ok(measureState({ machine, person: p, cell: cell('vo2max'), mission: { ...M, landing: '2026-12-10T12:00:00Z' }, now: M.today }).forecast, 'in flight the line is there');
  const rec = recovery({ machine, person: p, cells: CELLS, mission: M, now: M.today });
  assert.equal(rec.n, 14);
  const row = (k) => rec.rows.find((r) => r.key === k);
  assert.equal(row('vo2max').state, 'since');
  assert.equal(row('vo2max').pct, 80);
  assert.match(row('vo2max').text, /R\+7/);
  assert.match(row('vo2max').text, /\[V1 4004\]/);
  assert.match(row('vo2max').text, /Last test in flight: 81%/);
  assert.equal(row('strength').state, 'none');
  assert.match(row('strength').text, /within 5 to 7 days of landing/);
  assert.equal(row('bodyMass').value, 97);
  assert.equal(row('pulse').value, 84);
  assert.match(row('pulse').text, /about 70 bpm \(the middle of 3 readings\)/);
  assert.deepEqual(rec.sleep, { hours: 7.2, time: at('2026-11-15') });
  assert.ok(rec.rows.every((r) => !r.level), 'information only: nothing here raises a level');
  assert.match(recoveryLine('vo2max', rec), /^Aerobic capacity, back on Earth: Since landing/);
  assert.match(recoveryLine('temp', rec), /the forecast to landing ended at landing/);
  assert.equal(recoveryLine('temp', null), null);
});

test('PO-5: with no mission set there is no forecast, and nothing is explained away as a usual change of flight', () => {
  const none = { name: null, launch: null, landing: null, today: '2026-11-15T12:00:00.000Z', none: true };
  const M = { launch: '2026-06-01T12:00:00Z', landing: '2026-12-10T12:00:00Z', today: '2026-11-15T12:00:00.000Z' };
  assert.equal(hasMissionDates(none), false);
  assert.equal(hasMissionDates(null), false);
  assert.equal(hasMissionDates(M), true);
  const readings = [];
  ['2026-07-01', '2026-08-01', '2026-09-01', '2026-10-01', '2026-11-01'].forEach((d, i) => readings.push({ source: 'fitness-test', indicator: 'vo2max', value: 40 - 1.6 * i, time: `${d}T08:00:00.000Z` }));
  readings.push({ source: 'thermometer', indicator: 'temp', value: 37.6, time: '2026-11-15T08:00:00.000Z' });
  const machine = machineWith(readings);
  const p = person('crew-1');
  const now = '2026-11-15T12:00:00.000Z';
  assert.equal(measureState({ machine, person: p, cell: cell('vo2max'), mission: none, now }).forecast, null);
  assert.ok(measureState({ machine, person: p, cell: cell('vo2max'), mission: M, now }).forecast.line);
  const withM = assess({ machine, person: p, cells: CELLS, mission: M, now });
  const without = assess({ machine, person: p, cells: CELLS, mission: none, now });
  assert.ok(withM.body.items.some((x) => x.kind === 'forecast'), 'with the mission, the falling line is a forecast item');
  assert.ok(!without.body.items.some((x) => x.kind === 'forecast'), 'without it, none');
  assert.ok(withM.info.some((x) => x.kind === 'expected' && x.cell.indicator === 'temp'), 'in flight 37.6 is the usual rise');
  assert.ok(!without.info.some((x) => x.kind === 'expected'), 'with no flight known it is not explained away');
  assert.ok(without.info.some((x) => x.kind === 'watch' && x.cell.indicator === 'temp'));
  assert.equal(missionPhase(none, now).kind, 'none');
});

test('what to expect on return: plain words, each with a NASA source; the rules are drafts that keep the cells\' 80%', () => {
  assert.ok(RETURN_FACTS.length >= 4);
  for (const f of RETURN_FACTS) {
    assert.ok(f.text && !LONG_DASHES.test(f.text), f.key);
    assert.ok(f.src.length && f.src.every((s) => /^https:\/\/(www\.nasa\.gov|ntrs\.nasa\.gov)\//.test(s.url)), f.key);
  }
  assert.match(RETURN_FACTS.find((f) => f.key === 'readapt').text, /2 to 3 days/);
  assert.match(RETURN_FACTS.find((f) => f.key === 'watch').text, /30 to 45 days/);
  for (const s of Object.values(LANDING_SOURCES)) assert.match(s.url, /^https:\/\//);
  for (const ind of ['vo2max', 'strength']) assert.equal(cell(ind).norm.minPercent, LANDING_RULES.minPercent, ind);
  assert.equal(LANDING_RULES.eyeExamDaysBefore, 30);
  assert.equal(fmtDay('2026-12-10T18:00:00Z'), '10 Dec 2026');
});
